//! 🪆️ A checkpoint cascade retains one original authored metadata source and returns that exact parent authority after every child alias closes.
use super::*;
use semio_framework_value::retained_clone::{RetainedCloneSourceAdmission,NativeAllocationIdentity};
use semio_framework_job::{OriginalConstructionAdmission,OriginalConstructionFailure};
use semio_framework_value::{OriginalRetirementFailure,RetainedCloneStep};
use semio_plugin_job_receiving::original_steps::{begin,born,forgotten,forward,funds,moved,paid,produced,replied,retired,settle};
/// 🗂️ The actual fixed registry backing, admission generation and live count fence its dense member order.
pub type ChildRosterIdentity=(usize,u64,usize);
/// 📌️ Pins reserve their real canonical backing once; each child copies only the metadata it actually commits.
pub struct ChildCheckpointCascade{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),frame:OriginalConstructionAdmission,failure:ManuallyDrop<Option<OriginalConstructionFailure>>,body:usize,roster:ChildRosterIdentity,metadata:ManuallyDrop<Option<CheckpointMetadata>>,source:ManuallyDrop<Option<RetainedCloneSource<CheckpointMetadata>>>,admission:Option<RetainedCloneSourceAdmission<CheckpointMetadata,CheckpointMetadata,()>>,child:ManuallyDrop<Option<Box<ChildCheckpointUnit>>>,pins:ManuallyDrop<Option<Vec<CompositionPin>>>,pin:ManuallyDrop<Option<(bool,Option<CompositionPin>)>>,retirement:RetainedCloneClose,next:usize,changed:bool,phase:u8,closing:bool}
impl ChildCheckpointCascade{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<(Self,Option<CheckpointMetadata>)>()}}
 pub fn admit(metadata:&mut Option<CheckpointMetadata>,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,failure:&mut Option<OriginalConstructionFailure>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if output.is_none()&&metadata.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::capture_demands();born(cx,output,admission,failure,d,|native|Ok(Box::new(Self{binding,decoder:(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?),frame:Default::default(),failure:ManuallyDrop::new(None),body,roster,metadata:ManuallyDrop::new(metadata.take()),source:ManuallyDrop::new(None),admission:None,child:ManuallyDrop::new(None),pins:ManuallyDrop::new(None),pin:ManuallyDrop::new(None),retirement:Default::default(),next:0,changed:false,phase:0,closing:false})))}
 fn validate(&self,roster:ChildRosterIdentity,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder)||self.roster!=roster{return Err(invalid().into())}Ok(())}
 pub fn next_construction_demands<M:SpaceMember>(&self,member:Option<&M>)->Option<RetirementDemand>{if self.phase==2&&self.next!=self.roster.2{Some(ChildCheckpointUnit::capture_demands())}else{self.child.as_ref().and_then(|c|member.and_then(|m|c.next_construction_demands(m)))}}
 pub fn next(&self)->usize{self.next}
 pub fn roster(&self)->ChildRosterIdentity{self.roster}
 pub fn ready(&self)->bool{self.phase==8&&!self.closing}
 fn action(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut Self)->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{if !funds(cx,d){return Ok(false)}run(self)?;paid(cx,d)?;Ok(true)}
 pub fn advance<M:SpaceMember>(&mut self,roster:ChildRosterIdentity,mut member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.closing||cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original child checkpoint cascade was cancelled").into())}match self.phase{
 0=>{if self.admission.is_none(){let d=header::<(RetainedCloneSourceAdmission<CheckpointMetadata,CheckpointMetadata,()>,u8)>();self.action(cx,d,|s|{s.admission=Some(RetainedCloneSource::admission_owned(s.metadata.take().ok_or_else(invalid)?,()));Ok(())})?;return Ok(false)}let admission=self.admission.as_ref().ok_or_else(invalid)?;let ready=admission.phase()=="ready";let d=admission.next_demand()?;forward(cx,d,|effect|{let admission=self.admission.as_mut().expect("admission checked present");if ready{let turn=admission.take_output(&mut self.source,effect);settle(effect,turn.result)}else{{let turn=admission.advance(effect);settle(effect,turn.result)}}})?;if self.source.is_some(){self.admission=None;self.phase=1;}},
 1=>{let d=RetirementDemand{capacity_bytes:self.roster.2.checked_mul(size_of::<CompositionPin>()).ok_or_else(invalid)?,..header::<Vec<CompositionPin>>()};if funds(cx,d){let mut pins=Vec::new();pins.try_reserve_exact(self.roster.2).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original child checkpoint pin rows could not be reserved"))?;let mut p=semio_plugin_job_receiving::original_steps::receipt(d);p.retained_capacity_bytes=pins.capacity()*size_of::<CompositionPin>();*self.pins=Some(pins);self.phase=2;cx.consume_retained(p)?;cx.consume_fuel(1)}},
 2=>{if self.next==self.roster.2{self.action(cx,header::<u8>(),|s|{s.phase=7;Ok(())})?;}else if ChildCheckpointUnit::admit(cx,&mut self.frame,&mut self.failure,&mut self.child)?{self.phase=3;}},
 3=>{if self.child.as_mut().unwrap().advance(member.as_deref_mut().ok_or_else(invalid)?,self.source.as_ref().unwrap(),cx)?{self.phase=4;}},
 4=>{if self.child.as_mut().unwrap().take_pin(cx,&mut self.pin)?{self.phase=5;}},
 5=>{if self.close_child(member.as_deref_mut(),cx)?{self.action(cx,header::<u8>(),|s|{s.phase=6;Ok(())})?;}},
 6=>{self.action(cx,header::<(Option<(bool,Option<CompositionPin>)>,CompositionPin,usize,bool,u8)>(),|s|{let(changed,pin)=s.pin.take().ok_or_else(invalid)?;s.changed|=changed;if let Some(pin)=pin{let pins=s.pins.as_mut().unwrap();if pins.len()==pins.capacity(){return Err(invalid())}pins.push(pin);}s.next+=1;s.phase=2;Ok(())})?;},
 7=>{let source=self.source.as_mut().ok_or_else(invalid)?;let d=source.next_take_demand(self.body)?;let body=self.body;let metadata=&mut self.metadata;let mut taken=false;forward(cx,d,|effect|replied::<OriginalRetirementFailure>(effect,|effect,reply|{let mut out=None;let done=source.take_authority_into(&mut out,body,effect,reply)?;if let Some(value)=out{**metadata=Some(value);taken=true}Ok(done)}))?;if taken{self.source.take();self.phase=8}},8=>{},_=>return Err(invalid().into()),}Ok(self.ready())}
 pub fn take(&mut self,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,output:&mut Option<(CheckpointMetadata,Vec<CompositionPin>,bool)>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if !self.ready(){return Err(invalid().into())}let d=header::<(CheckpointMetadata,Vec<CompositionPin>,bool,u8)>();if produced(cx,d,output,||Ok((self.metadata.take().ok_or_else(invalid)?,self.pins.take().ok_or_else(invalid)?,self.changed)))?{self.phase=9;return Ok(true)}Ok(false)}
 fn close_child<M:SpaceMember>(&mut self,member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(child)=self.child.as_mut()else{return Ok(true)};if !child.terminal_is_empty(){cx.with_original_retirement(|cx|child.close_step(member.ok_or_else(invalid)?,cx))?;return Ok(false)}let mut d=ChildCheckpointUnit::release_demands();d.copy_bytes=size_of::<Option<Box<ChildCheckpointUnit>>>();forgotten(cx,d,||{self.child.take();})?;Ok(false)}
 pub fn close_demands<M:SpaceMember>(&self,member:Option<&M>)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(child)=self.child.as_ref(){return if child.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildCheckpointUnit>>>(),..ChildCheckpointUnit::release_demands()})}else{child.close_demands(member.ok_or_else(invalid)?)}}if let Some(admission)=self.admission.as_ref(){return if admission.phase()=="ready"{admission.next_demand()}else{admission.next_return_demand()}}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(header::<Option<RetainedCloneSource<CheckpointMetadata>>>())}else{source.next_close_demand(self.body)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<CheckpointMetadata>(true,&None,self.body)}if self.pins.is_some(){return self.retirement.next_owner_demands::<Vec<CompositionPin>>(true,&None,self.body)}if self.pin.is_some(){return self.retirement.next_owner_demands::<(bool,Option<CompositionPin>)>(true,&None,self.body)}if self.failure.is_some(){return self.retirement.next_owner_demands::<OriginalConstructionFailure>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step<M:SpaceMember>(&mut self,roster:ChildRosterIdentity,member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(member.as_deref())?;if !self.closing{if funds(cx,d){self.closing=true;paid(cx,d)?}return Ok(false)}if !self.close_child(member,cx)?{return Ok(false)}if !self.retirement.is_empty(){retired(cx,d,|effect|self.retirement.step_granted(effect.grant().maximum_copy_bytes,effect))?;return Ok(false)}
  if self.admission.is_some(){let ready=self.admission.as_ref().is_some_and(|a|a.phase()=="ready");retired(cx,d,|effect|{let admission=self.admission.as_mut().expect("admission checked present");if ready{let turn=admission.take_output(&mut self.source,effect);let result=turn.result.map(|step|RetainedCloneStep::Progress(step.progress()));if self.source.is_some(){self.admission=None;}return settle(effect,result)}let mut inputs=None;let turn=admission.return_inputs(&mut inputs,effect);let result=turn.result.map(|step|{if let Some((metadata,()))=inputs{*self.metadata=Some(metadata);}RetainedCloneStep::Progress(step.progress())});if admission.terminal_is_empty(){self.admission=None;}settle(effect,result)})?;return Ok(false)}
  if let Some(source)=self.source.as_mut(){if !source.terminal_is_empty(){retired(cx,d,|effect|source.close_step(self.body,effect))?;return Ok(false)}forgotten(cx,d,||{self.source.take();})?;return Ok(false)}
  if self.metadata.is_some(){retired(cx,d,|effect|begin(&mut self.retirement,&mut self.metadata,effect))?;return Ok(false)}
  if self.pins.is_some(){retired(cx,d,|effect|begin(&mut self.retirement,&mut self.pins,effect))?;return Ok(false)}
  if self.pin.is_some(){retired(cx,d,|effect|begin(&mut self.retirement,&mut self.pin,effect))?;return Ok(false)}
  if self.failure.is_some(){retired(cx,d,|effect|begin(&mut self.retirement,&mut self.failure,effect))?;return Ok(false)}
  if !self.frame.terminal_is_empty(){self.frame.close_step(cx)?;return Ok(false)}
  Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.failure.is_none()&&self.frame.terminal_is_empty()&&self.metadata.is_none()&&self.source.is_none()&&self.admission.is_none()&&self.child.is_none()&&self.pins.is_none()&&self.pin.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for ChildCheckpointCascade{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child checkpoint cascade requires funded closure")}}
